sys_variable_value.value:
(function() {
    var planGr = new GlideRecord('x_1919740_dayone_0_onboarding_plan');
    planGr.initialize();
    planGr.setValue('employee_name', 'ATF Gate Pass');
    planGr.setValue('employee_id', 'ATF-009');
    planGr.setValue('state', 'active');
    planGr.setValue('readiness_threshold', 100);
    var planId = planGr.insert();

    for (var i = 1; i <= 2; i++) {
        var t = new GlideRecord('x_1919740_dayone_0_onboarding_task');
        t.initialize();
        t.setValue('plan', planId);
        t.setValue('task_name', 'Mandatory Task ' + i);
        t.setValue('mandatory', true);
        t.setValue('task_state', 'complete');
        t.setValue('evidence_verified', true);
        t.setValue('department', 'hr');
        t.insert();
    }

    var optTask = new GlideRecord('x_1919740_dayone_0_onboarding_task');
    optTask.initialize();
    optTask.setValue('plan', planId);
    optTask.setValue('task_name', 'Optional Complete');
    optTask.setValue('mandatory', false);
    optTask.setValue('task_state', 'complete');
    optTask.setValue('evidence_verified', true);
    optTask.setValue('department', 'facilities');
    optTask.insert();

    var gate = new DayOneGateValidator(planId);
    var result = gate.validateGate();
    if (!result.passed) throw new Error('Gate should pass but failed: ' + result.reasons.join('; '));
    gs.info('T-09 PASSED: Gate correctly passed with all mandatory tasks verified');
})();
